 pub(crate) fn prepare_catalog_storage(
     file: &FileEntry,
     single: &BTreeMap<String, TypedFacts>,
 ) -> Result<Vec<u8>> {
+    let prepared = prepare_catalog_rows(file, single)?;
+    let mut bytes = Vec::new();
+    write_catalog_bytes(&mut bytes, &serde_json::to_vec(&prepared.facts)?)?;
+    for values in [
