+        let leaves = prepared
+            .leaves
+            .get(domain)
+            .context("missing prepared domain")?;
+        write_catalog_len(&mut bytes, leaves.len())?;
+        for (key, value) in leaves {
+            write_catalog_bytes(&mut bytes, key.as_bytes())?;
+            write_catalog_bytes(&mut bytes, value.as_bytes())?;
+        }
+    }
+    let mut compressed = zstd::stream::encode_all(bytes.as_slice(), -3)?;
+    compressed.shrink_to_fit();
+    Ok(compressed)
+}
+
+fn write_catalog_len(bytes: &mut Vec<u8>, length: usize) -> Result<()> {
+    bytes.extend_from_slice(&u32::try_from(length)?.to_le_bytes());
+    Ok(())
+}
+
+fn write_catalog_bytes(bytes: &mut Vec<u8>, value: &[u8]) -> Result<()> {
+    write_catalog_len(bytes, value.len())?;
+    bytes.extend_from_slice(value);
+    Ok(())
+}
+
+fn read_catalog_len(bytes: &mut &[u8]) -> Result<usize> {
+    anyhow::ensure!(bytes.len() >= 4, "truncated catalog storage length");
+    let (length, rest) = bytes.split_at(4);
+    *bytes = rest;
+    Ok(u32::from_le_bytes(length.try_into()?) as usize)
+}
+
+fn read_catalog_bytes<'a>(bytes: &mut &'a [u8]) -> Result<&'a [u8]> {
+    let length = read_catalog_len(bytes)?;
+    anyhow::ensure!(length <= bytes.len(), "truncated catalog storage value");
+    let (value, rest) = bytes.split_at(length);
+    *bytes = rest;
+    Ok(value)
+}
+
+fn read_catalog_string(bytes: &mut &[u8]) -> Result<String> {
+    Ok(std::str::from_utf8(read_catalog_bytes(bytes)?)?.to_owned())
+}
+
+fn read_catalog_strings(bytes: &mut &[u8]) -> Result<Vec<String>> {
+    let count = read_catalog_len(bytes)?;
+    anyhow::ensure!(
+        count <= bytes.len() / 4,
+        "truncated catalog storage strings"
+    );
+    (0..count).map(|_| read_catalog_string(bytes)).collect()
+}
+
+fn decode_catalog_storage(compressed: &[u8]) -> Result<PreparedCatalogStorage> {
+    let decoded = zstd::stream::decode_all(compressed)?;
+    let mut bytes = decoded.as_slice();
+    let facts = serde_json::from_slice(read_catalog_bytes(&mut bytes)?)?;
+    let details_json = read_catalog_strings(&mut bytes)?;
+    let search_texts = read_catalog_strings(&mut bytes)?;
+    let reference_keys = read_catalog_strings(&mut bytes)?;
+    let mut domains = BTreeMap::new();
+    for domain in ["nodes", "doc_sections", "shared_owners"] {
+        let count = read_catalog_len(&mut bytes)?;
+        anyhow::ensure!(count <= bytes.len() / 8, "truncated catalog storage leaves");
+        let mut leaves = BTreeMap::new();
+        for _ in 0..count {
+            let key = read_catalog_string(&mut bytes)?;
+            let value = read_catalog_string(&mut bytes)?;
+            anyhow::ensure!(
+                leaves.insert(key, value).is_none(),
+                "duplicate catalog leaf"
+            );
+        }
+        domains.insert(domain.to_owned(), leaves);
+    }
+    anyhow::ensure!(bytes.is_empty(), "trailing catalog storage bytes");
+    Ok(PreparedCatalogStorage {
+        facts,
+        details_json,
+        search_texts,
+        reference_keys,
+        leaves: domains,
+    })
+}
